import csv, io, re
from datetime import datetime
from zoneinfo import ZoneInfo
import pandas as pd
from pydantic import BaseModel, ValidationError, field_validator

raw = open("orders.csv", "rb").read()         # bytes, not text yet
try:
    text = raw.decode("utf-8-sig")            # UTF-8, BOM removed if present
except UnicodeDecodeError:
    text = raw.decode("cp1252")               # common Windows Excel export
rows = csv.DictReader(io.StringIO(text), delimiter=";")

ORDER_ID = re.compile(r"ORD-\d{6}")
LONDON, UTC = ZoneInfo("Europe/London"), ZoneInfo("UTC")

class Order(BaseModel):
    order_id: str
    placed_at: datetime                       # always stored in UTC

    @field_validator("order_id")
    @classmethod
    def find_id(cls, v: str) -> str:
        m = ORDER_ID.search(v)                # "ref ORD-004417 " -> "ORD-004417"
        if not m:
            raise ValueError("no order id found")
        return m.group()

good, bad = [], []
for r in rows:
    local = datetime.strptime(r["placed"], "%d/%m/%Y %H:%M").replace(tzinfo=LONDON)
    try:
        good.append(Order(order_id=r["ref"], placed_at=local.astimezone(UTC)))
    except ValidationError as e:
        bad.append({**r, "reason": e.errors()[0]["msg"]})

pd.DataFrame([o.model_dump() for o in good]).to_parquet("orders.parquet")
pd.DataFrame(bad).to_csv("orders_rejected.csv", index=False)
